/** bool8 ScrCmd_fadescreenswapbuffers(struct ScriptContext *ctx) */
export function ScrCmd_fadescreenswapbuffers(...args: any[]): any {
  let mode = ScriptReadByte(ctx);

      switch (mode)
      {
      case FADE_TO_BLACK:
      case FADE_TO_WHITE:
      default:
          CpuCopy32(gPlttBufferUnfaded, gPaletteDecompressionBuffer, PLTT_SIZE);
          FadeScreen(mode, 0);
          break;
      case FADE_FROM_BLACK:
      case FADE_FROM_WHITE:
          CpuCopy32(gPaletteDecompressionBuffer, gPlttBufferUnfaded, PLTT_SIZE);
          FadeScreen(mode, 0);
          break;
      }

      SetupNativeScript(ctx, IsPaletteNotActive);
      return TRUE;
}

